// Post-processes the collection generated by openapi-to-postmanv2.
// Usage: node postprocess-postman.js <collection.json> <environment.json>
const fs = require('fs');
const [collectionPath, environmentPath] = process.argv.slice(2);
const c = JSON.parse(fs.readFileSync(collectionPath, 'utf8'));

const json = (o) => JSON.stringify(o, null, 2);
const saveToken = [
  'if (pm.response.code === 200) {',
  '  const body = pm.response.json();',
  "  pm.collectionVariables.set('accessToken', body.data.accessToken);",
  '}',
];
const saveId = (name) => [
  'if (pm.response.code === 201) {',
  `  pm.collectionVariables.set('${name}', pm.response.json().data.id);`,
  '}',
];

// key: "METHOD path" → short name, sample body, test script
const spec = {
  'POST api/v1/auth/register': {
    name: 'Register',
    body: { firstName: 'Jamie', lastName: 'Rivera', email: '{{newUserEmail}}', password: '{{newPassword}}', confirmPassword: '{{newPassword}}' },
  },
  'POST api/v1/auth/login': { name: 'Login', body: { email: '{{email}}', password: '{{password}}' }, test: saveToken },
  'POST api/v1/auth/refresh': { name: 'Refresh token', test: saveToken },
  'POST api/v1/auth/logout': { name: 'Logout', test: ["pm.collectionVariables.set('accessToken', '');"] },
  'GET api/v1/users/me': { name: 'Get my profile' },
  'PUT api/v1/users/me': { name: 'Update my profile', body: { firstName: 'Alex', lastName: 'Admin' } },
  'POST api/v1/users/me/password': {
    name: 'Change my password',
    body: { currentPassword: '{{password}}', newPassword: '{{newPassword}}', confirmNewPassword: '{{newPassword}}' },
    test: saveToken,
  },
  'GET api/v1/users': { name: 'List users (admin)' },
  'POST api/v1/users': {
    name: 'Create user (admin)',
    body: {
      firstName: 'Jamie',
      lastName: 'Rivera',
      email: '{{newUserEmail}}',
      password: '{{newPassword}}',
      confirmPassword: '{{newPassword}}',
      role: 'ProjectManager',
    },
    test: saveId('userId'),
  },
  'GET api/v1/users/lookup': { name: 'Look up users' },
  'GET api/v1/users/:id': { name: 'Get user (admin)' },
  'PATCH api/v1/users/:id/role': { name: 'Change user role (admin)', body: { role: 'ProjectManager' } },
  'POST api/v1/users/:id/activate': { name: 'Activate user (admin)' },
  'POST api/v1/users/:id/deactivate': { name: 'Deactivate user (admin)' },
  'GET api/v1/projects': { name: 'List projects' },
  'POST api/v1/projects': {
    name: 'Create project',
    body: { name: 'Website relaunch', description: 'Redesign and relaunch the public website.', startDate: '{{today}}', endDate: '{{nextMonth}}' },
    test: saveId('projectId'),
  },
  'GET api/v1/projects/:id': { name: 'Get project' },
  'PUT api/v1/projects/:id': {
    name: 'Update project',
    body: { name: 'Website relaunch', description: 'Redesign, migrate content and relaunch.', startDate: '{{today}}', endDate: '{{nextMonth}}' },
  },
  'DELETE api/v1/projects/:id': { name: 'Delete project' },
  'POST api/v1/projects/:id/members': { name: 'Add project member', body: { userId: '{{userId}}' } },
  'DELETE api/v1/projects/:id/members/:userId': { name: 'Remove project member' },
  'GET api/v1/projects/:projectId/tasks': { name: 'List project tasks' },
  'POST api/v1/projects/:projectId/tasks': {
    name: 'Create task',
    body: { title: 'Write release notes', description: 'Draft the release notes for version 1.0.', priority: 'High', dueDate: '{{nextWeek}}', assigneeId: null },
    test: saveId('taskId'),
  },
  'GET api/v1/tasks': { name: 'List visible tasks' },
  'GET api/v1/tasks/:id': { name: 'Get task' },
  'PUT api/v1/tasks/:id': {
    name: 'Update task',
    body: { title: 'Write release notes', description: 'Draft and review the release notes for version 1.0.', priority: 'Critical', dueDate: '{{nextWeek}}' },
  },
  'DELETE api/v1/tasks/:id': { name: 'Delete task' },
  'PATCH api/v1/tasks/:id/status': { name: 'Change task status', body: { status: 'InProgress' } },
  'PATCH api/v1/tasks/:id/assignee': { name: 'Assign task', body: { assigneeId: '{{userId}}' } },
  'GET api/v1/dashboard': { name: 'Get dashboard' },
  'POST api/v1/ai/task-descriptions/improve': {
    name: 'Improve task description (AI)',
    body: { title: 'Login page', description: 'make login page, needs email and pw, show error if wrong' },
  },
};

// Query parameters that are enabled by default (everything else stays in the request, disabled).
const enabledQuery = { pageNumber: '1', pageSize: '10', upcomingDays: '7', search: '' };
const pathVariable = (folder, key) => {
  if (key === 'projectId') return '{{projectId}}';
  if (key === 'userId') return '{{userId}}';
  return { Projects: '{{projectId}}', Tasks: '{{taskId}}', Users: '{{userId}}' }[folder] ?? '<uuid>';
};

const seen = new Set();
for (const folder of c.item) {
  if (folder.name === 'Auth') {
    folder.auth = { type: 'noauth' };
  }
  for (const item of folder.item) {
    const r = item.request;
    const key = `${r.method} ${r.url.path.join('/')}`;
    const s = spec[key];
    if (!s) throw new Error(`No spec for ${key}`);
    seen.add(key);

    item.request.description = { content: `${item.name}\n\n${r.description?.content ?? ''}`.trim(), type: 'text/plain' };
    item.name = s.name;
    r.name = s.name;
    delete r.auth; // inherit: bearer at collection level, noauth for the Auth folder

    for (const v of r.url.variable ?? []) v.value = pathVariable(folder.name, v.key);
    for (const q of r.url.query ?? []) {
      // Model binding is case-insensitive; use the camelCase names the Angular client sends.
      q.key = q.key.charAt(0).toLowerCase() + q.key.slice(1);
      if (q.key in enabledQuery) {
        q.value = enabledQuery[q.key];
        q.disabled = q.key === 'search' && key !== 'GET api/v1/users/lookup';
      } else {
        q.value = '';
        q.disabled = true;
      }
    }
    if (s.body) {
      r.body = { mode: 'raw', raw: json(s.body), options: { raw: { language: 'json' } } };
    }
    item.event = s.test ? [{ listen: 'test', script: { type: 'text/javascript', exec: s.test } }] : [];
    // Drop generated example responses: they contain placeholder values only.
    item.response = [];
  }
}
const missing = Object.keys(spec).filter((k) => !seen.has(k));
if (missing.length) throw new Error(`Endpoints not in the OpenAPI document: ${missing.join(', ')}`);

c.info.name = 'Smart Task Management API';
c.info.description = [
  'Generated from docs/api/openapi.json (Swashbuckle) with openapi-to-postmanv2, then post-processed.',
  '',
  '1. Select the "Smart Task - Local" environment and fill in email and password (e.g. a seeded or bootstrap admin).',
  '2. Run Auth > Login. The test script stores the access token in {{accessToken}}; Postman keeps the refresh cookie.',
  '3. Every other request sends Authorization: Bearer {{accessToken}}. Run Auth > Refresh token when it expires (15 min).',
  '4. Create project / Create task / Create user store {{projectId}}, {{taskId}} and {{userId}} for the requests that follow.',
].join('\n');
c.auth = { type: 'bearer', bearer: [{ key: 'token', value: '{{accessToken}}', type: 'string' }] };
c.variable = [
  { key: 'baseUrl', value: 'https://localhost:7180' },
  { key: 'accessToken', value: '' },
  { key: 'projectId', value: '' },
  { key: 'taskId', value: '' },
  { key: 'userId', value: '' },
];
// Valid dates for the sample bodies (a new project may not start in the past; a new task may not be due in the past).
c.event = [
  {
    listen: 'prerequest',
    script: {
      type: 'text/javascript',
      exec: [
        'const day = (offset) => { const d = new Date(); d.setUTCDate(d.getUTCDate() + offset); return d.toISOString().slice(0, 10); };',
        "pm.variables.set('today', day(0));",
        "pm.variables.set('nextWeek', day(7));",
        "pm.variables.set('nextMonth', day(30));",
      ],
    },
  },
];
fs.writeFileSync(collectionPath, json(c) + '\n');

const environment = {
  name: 'Smart Task - Local',
  values: [
    { key: 'baseUrl', value: 'https://localhost:7180', type: 'default', enabled: true },
    { key: 'email', value: '', type: 'default', enabled: true },
    { key: 'password', value: '', type: 'secret', enabled: true },
    { key: 'newUserEmail', value: '', type: 'default', enabled: true },
    { key: 'newPassword', value: '', type: 'secret', enabled: true },
  ],
  _postman_variable_scope: 'environment',
};
fs.writeFileSync(environmentPath, json(environment) + '\n');
console.log(`OK: ${seen.size} requests`);
